/bin/zsh -lc "python -c 'import pandas as pd, numpy as np, json, math
D=pd.read_csv(\"respondents.csv\");M=json.load(open(\"study_materials.json\"));C=json.load(open(\"codebook.json\"));w=D.wt_final
print(\"SAMPLE\",len(D),D.respondent_id.nunique(),w.sum(),w.sum()**2/(w*w).sum())
def base(v,e=None):
 if e is None:e=np.ones(len(D),dtype=bool)
 z=w[v];return [int(np.sum(e)),round(float(w[e].sum()),3),int(np.sum(v)),round(float(z.sum()),3),round(float(z.sum()**2/(z*z).sum()),3)]
for status,cols in [(\"needs_block_status\",[\"support_quick_meals\",\"support_use_up\",\"support_budget\",\"support_shared_plan\"]),(\"barriers_block_status\",[\"barrier_setup_time\",\"barrier_rigid\",\"barrier_cost\",\"barrier_privacy\"])]:
 v=D[status].eq(1);print(status,base(v),[round(100*np.average(D.loc[v,c],weights=w[v]),3) for c in cols],\"none\",100*w[v&D[cols].eq(0).all(axis=1)].sum()/w[v].sum(),\"missing\",D[status].value_counts().to_dict());print(\"block_errors\",sum(not (all(row[c] in [0,1] for c in cols) if row[status]==1 else all(row[c]==row[status] for c in cols)) for _,row in D.iterrows()))
for var in C[\"variables\"]:
 c=var[\"name\"]
 if var[\"valid_codes\"]==[1,2,3,4,5] or c in [\"planning_tool_28d\",\"shared_list_use_28d\"]:
  e=D.planning_tool_28d.isin([1,2,3]) if c in [\"tool_satisfaction_5\",\"shared_list_use_28d\"] else np.ones(len(D),dtype=bool);v=e&D[c].isin(var[\"valid_codes\"]);print(c,base(v,e),[round(100*w[v&D[c].eq(k)].sum()/w[v].sum(),3) for k in var[\"valid_codes\"]],\"missing\",int((e&D[c].eq(97)).sum()),int((e&D[c].eq(98)).sum()),\"blank\",int(D[c].isna().sum()))
for c,inputs in M[\"need_state_policy\"][\"derivation\"].items():
 v=D[inputs].isin(range(1,6)).all(axis=1);expected=np.where(v,D[inputs].ge(4).all(axis=1).astype(int),99);print(c,base(v),100*w[v&D[c].eq(1)].sum()/w[v].sum(),\"unknown\",int((~v).sum()),\"errors\",int((expected"'!=D[c]).sum()))
v=D[["need_budget","need_effort","need_waste"]].isin([0,1]).all(axis=1);print("JOINT",base(v),D.loc[v].assign(comb=D.loc[v,["need_budget","need_effort","need_waste"]].astype(str).agg("".join,axis=1)).groupby("comb").wt_final.sum().div(w[v].sum()).mul(100).to_dict())
res=[]
for t in M["required_inference"]["estimands"]:
 g=D[t["group_variable"]];y=D[t["outcome"]];valid=y.isin([0,1] if t["outcome"]=="over_budget_4w" else range(8));a=np.zeros(len(D));means=[];bs=[]
 for k in [1,0]:
  e=g.eq(k);v=e&valid;mu=np.average(y[v],weights=w[v]);means.append(mu);bs.append(base(v,e)+[int((e&y.eq(97)).sum()),int((e&y.eq(98)).sum())]);a[v]+=(1 if k==1 else -1)*w[v]*(y[v]-mu)/w[v].sum()
 variance=0
 for _,ix in D.groupby(["age_band","children_u16"]).groups.items():
  z=a[ix];variance+=len(z)/(len(z)-1)*sum((z-z.mean())**2)
 scale=100 if t["unit"]=="percentage_points" else 1;diff=(means[0]-means[1])*scale;se=variance**.5*scale;p=math.erfc(abs(diff/se)/2**.5);res.append(dict(id=t["id"],family=t["family"],bases=bs,means=[x*scale for x in means],diff=diff,se=se,ci=[diff-1.959963984540054*se,diff+1.959963984540054*se],p=p))
for family in M["required_inference"]["families"]:
 r=sorted([x for x in res if x["family"]==family],key=lambda x:x["p"]);last=0
 for i,x in enumerate(r):last=max(last,min(1,(len(r)-i)*x["p"]));x["holm_p"]=last
print("CONTRASTS",json.dumps(res))
e=D.age_band.eq(4)&D.planning_tool_28d.eq(3);v=e&D.tool_satisfaction_5.isin(range(1,6));print("SUPPRESSED",base(v,e));print("QUOTAS",D.groupby(["age_band","children_u16"]).agg(n=("wt_final","size"),weight_min=("wt_final","min"),weight_max=("wt_final","max")).to_string())'"'"

